"use strict";(globalThis.webpackChunkfiles_hub_docs=globalThis.webpackChunkfiles_hub_docs||[]).push([[2932],{7030(e){e.exports=JSON.parse('{"tag":{"label":"email-marketing","permalink":"/tags/email-marketing","allTagsPath":"/tags","count":9,"items":[{"id":"email-marketing/product-integration","title":"Connect your product to email marketing","description":"The recipe every product follows to connect FilesHub email marketing \u2014 carry the ?c= contact token through sign-up, report signed_up and activated events from the server, and add a double opt-in form.","permalink":"/email-marketing/product-integration"},{"id":"email-marketing/batches","title":"Contact batches","description":"Each imported CSV becomes one numbered batch in the shared people pool. A batch is given to one product\'s campaign at a time, never to the same product twice, and every use is recorded with its results.","permalink":"/email-marketing/batches"},{"id":"email-marketing/contact-cleaning","title":"Contact cleaning","description":"How FilesHub checks every address in the shared contact pool before a campaign mails it \u2014 address rules, DNS, an AI review of company domains, bounce history and a mailbox check with the recipient\'s own server \u2014 and how a project paused for bounces resumes by itself.","permalink":"/email-marketing/contact-cleaning"},{"id":"email-marketing/api","title":"Email marketing API","description":"Endpoints for FilesHub email marketing \u2014 lists, contacts, paste and CSV imports, suppressions, sequences, enrollment, test sends, product events and the public subscribe form \u2014 on the data plane and the management plane.","permalink":"/email-marketing/api"},{"id":"email-marketing/overview","title":"Email marketing overview","description":"FilesHub email marketing keeps per-project contact lists, imports contacts by CSV, paste or one at a time, and sends drip sequences that branch on clicks and product events \u2014 with consent, suppression and one-click unsubscribe built in.","permalink":"/email-marketing/overview"},{"id":"email-marketing/deliverability","title":"Mailbox warm-up and deliverability","description":"How FilesHub warms up every sending mailbox with persona conversations, measures real replies, tunes each mailbox\'s daily limit every night, and exposes the numbers and controls on the Management API.","permalink":"/email-marketing/deliverability"},{"id":"email-marketing/send-log","title":"Send log and campaign report","description":"Which email went to whom, from which campaign, step and mailbox, and what happened after \u2014 plus the stored campaign report with the waiting queue and a forecast date.","permalink":"/email-marketing/send-log"},{"id":"email-marketing/cross-campaign-gap","title":"The gap between campaigns","description":"A person who received a campaign email gets no email from a different campaign for 20 days. Follow-ups of a campaign already running for that person keep their own timing.","permalink":"/email-marketing/cross-campaign-gap"},{"id":"email-marketing/people-pool","title":"The shared people pool","description":"One pool of people for the whole FilesHub account \u2014 a contact imported once can join a list of any project without a second upload, with one history per person across products.","permalink":"/email-marketing/people-pool"}],"unlisted":false}}')}}]);